package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import dev.veltraph.client.gui.MenuSnapshot;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Source95BazaarLegTest {
 private long event;
 private Source95ChatReceipts.Receipt receipt(String line){return new Source95ChatReceipts.Receipt(++event,new Source95ChatReceipts.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),4),line,false);}
 private Source95AcquisitionBinding binding(){return new Source95AcquisitionBinding(BuilderCropType.WHEAT,"Private Seeds","@vanilla",Set.of("Private Seeds"),Map.of("instant","Private Instant","stack","Private Stack"),500,100,30000);}
 private MenuSnapshot menu(int revision,int quantity){return new MenuSnapshot(4,"Private Seeds",List.of(new MenuSnapshot.Slot(13,"Private Stack",List.of("Item: Private Seeds","Amount: "+quantity+"x","Price: 192 Coins"),false,"minecraft:paper",1,false)),revision);}
 @Test void sameItemPickupAndReadCountCannotCreditLegWithoutMatchedReceipt(){var leg=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),1000,true);assertEquals(Source95BazaarLeg.Kind.CLICK,leg.tick(binding(),menu(1,64),false,1000,500).kind());leg.tick(binding(),menu(2,64),false,1064,500);assertEquals(Source95BazaarLeg.State.ACK,leg.state());leg.message(receipt("Picked up64Private Seeds"),binding());leg.tick(binding(),menu(3,64),false,1064,500);assertEquals(Source95BazaarLeg.State.ACK,leg.state());leg.message(receipt("[Bazaar] Bought 64x Private Seeds for 192 coins!"),binding());leg.tick(binding(),menu(4,64),false,1064,500);assertEquals(Source95BazaarLeg.State.COMPLETE,leg.state());}
 @Test void quoted64CannotBeReplacedBy128OrAQuoteOverRemainingAggregateCap(){var a=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),127,true);assertEquals(Source95BazaarLeg.Kind.NONE,a.tick(binding(),menu(1,128),false,127,500).kind());assertEquals(Source95BazaarLeg.State.FAILED,a.state());var b=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),191,true);b.tick(binding(),menu(2,64),false,191,108);assertEquals(Source95BazaarLeg.State.FAILED,b.state());}
 @Test void awaitingLegNeverReissuesClickAndWrongProductOrQuantityStops(){var a=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),127,true);a.tick(binding(),menu(1,64),false,127,500);assertEquals(Source95BazaarLeg.Kind.NONE,a.tick(binding(),menu(2,64),false,127,500).kind());a.message(receipt("[Bazaar] Bought 64x Other Seeds for 192 coins!"),binding());assertEquals(Source95BazaarLeg.State.FAILED,a.state());var b=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),127,true);b.tick(binding(),menu(1,64),false,127,500);b.message(receipt("[Bazaar] Bought 63x Private Seeds for 192 coins!"),binding());assertEquals(Source95BazaarLeg.State.FAILED,b.state());}
 @Test void explicitlyUnboundStackControlHasNoDefaultClick(){var b=new Source95AcquisitionBinding(BuilderCropType.WHEAT,"Private Seeds","@vanilla",Set.of("Private Seeds"),Map.of("instant","Private Instant"),500,100,30000);var a=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),0,true);assertEquals(Source95BazaarLeg.Kind.NONE,a.tick(b,menu(1,64),false,0,500).kind());assertEquals(Source95BazaarLeg.State.FAILED,a.state());}
}
